    overlay.style.cssText = 'position:fixed;left:0;right:0;top:0;bottom:0;z-index:10001;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;';
    var box = document.createElement('div');
    box.style.cssText = 'width:86%;max-height:70%;background:#fff;border-radius:16px;padding:16px;box-sizing:border-box;';
    var title = document.createElement('h3');
    title.textContent = 'KGM 转换';
    title.style.cssText = 'flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:0;font-size:16px;';
    var path = document.createElement('div');
    path.textContent = file;
    path.style.cssText = 'font-size:12px;color:#666;word-break:break-all;margin-bottom:12px;';
    var status = document.createElement('div');
    status.textContent = '转换中...';
    status.style.cssText = 'font-size:14px;color:#333;margin-bottom:12px;';
