    close.textContent = '关闭';
    close.style.cssText = 'border:none;background:#f0f0f0;color:#333;border-radius:6px;padding:8px 16px;font-size:13px;cursor:pointer;';
    close.addEventListener('click', function(){ overlay.remove(); });
    box.appendChild(title); box.appendChild(path); box.appendChild(status); box.appendChild(close);
    overlay.appendChild(box);
    document.body.appendChild(overlay);

