(function(){
  var sleepTimer = null;
  function makeMenuItem(label, onClick){
    var item = document.createElement('button');
    item.type = 'button';
    item.textContent = label;
    item.style.cssText = 'display:flex;width:100%;align-items:center;gap:8px;border:none;background:transparent;padding:10px 14px;font-size:13px;text-align:left;cursor:pointer;white-space:nowrap;';
    item.addEventListener('click', function(e){
      e.stopPropagation();
      var menu = this.closest('.moe-sleep-menu');
      if(menu) menu.style.display = 'none';
      if(typeof onClick === 'function') onClick(this);
    });
    return item;
  }
  function doSleepTimer(item){
    try{
      var input = window.prompt('定时关闭（分钟），输入 0 取消', sleepTimer ? '0' : '30');
      if(input === null) return;
      var mins = parseInt(input, 10);
      if(isNaN(mins) || mins <= 0){
        if(sleepTimer){ clearTimeout(sleepTimer); sleepTimer = null; item.textContent = '定时关闭'; }
        return;
      }
      if(sleepTimer) clearTimeout(sleepTimer);
      item.textContent = '定时关闭 (' + mins + '分钟)';
      sleepTimer = setTimeout(function(){
        try{
          var a = document.querySelector('audio');
          if(a && !a.paused) a.pause();
        }catch(e){}
        item.textContent = '定时关闭';
        sleepTimer = null;
      }, mins * 60 * 1000);
    }catch(e){}
  }
  function doTranslation(){
    var btn = document.querySelector('.lyrics-screen .lyrics-mode-btn');
    if(!btn){
      try{
        if(window.$message && window.$message.info) window.$message.info('当前歌曲暂不支持翻译/音译');
        else alert('当前歌曲暂不支持翻译/音译');
      }catch(e){}
      return;
    }
    try{
      btn.style.setProperty('display','inline-flex','important');
      btn.style.setProperty('visibility','visible','important');
      btn.click();
      setTimeout(function(){
        btn.style.removeProperty('display');
        btn.style.removeProperty('visibility');
      }, 80);
    }catch(e){}
  }
  function addSleepMenu(){
    var oldBtn = document.querySelector('.moe-sleep-menu-btn');
    var oldMenu = document.querySelector('.moe-sleep-menu');
    var screen = document.querySelector('.lyrics-screen');
    if(!screen){
      if(oldBtn) oldBtn.remove();
      if(oldMenu) oldMenu.remove();
      return;
    }
    if(oldBtn) return;
    var btn = document.createElement('button');
    btn.className = 'moe-sleep-menu-btn';
    btn.title = '更多';
    btn.innerHTML = '<i class="fas fa-ellipsis-h"></i>';
    btn.style.cssText = 'position:fixed;top:calc(env(safe-area-inset-top) + 12px);right:16px;z-index:99999;width:36px;height:36px;border:none;background:rgba(0,0,0,.35);color:#fff;border-radius:50%;font-size:15px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;';
    var menu = document.createElement('div');
    menu.className = 'moe-sleep-menu';
    menu.style.cssText = 'position:fixed;top:calc(env(safe-area-inset-top) + 56px);right:16px;z-index:100000;background:#fff;color:#333;border-radius:10px;padding:6px 0;box-shadow:0 4px 12px rgba(0,0,0,.2);display:none;min-width:150px;';
    var dlItem = makeMenuItem('下载', function(){
      try{
        if(window.__moeDownloadQualityMenu) window.__moeDownloadQualityMenu();
        else alert('下载功能暂不可用');
      }catch(e){}
    });
    var sleepItem = makeMenuItem('定时关闭', function(item){ doSleepTimer(item); });
    var trItem = makeMenuItem('翻译', function(){ doTranslation(); });
    var kgmItem = makeMenuItem('KGM 转换', function(){
      try{
        if(window.__moeKgmConvertPrompt) window.__moeKgmConvertPrompt();
        else alert('KGM 转换功能暂不可用');
      }catch(e){}
    });
    menu.appendChild(dlItem);
    menu.appendChild(sleepItem);
    menu.appendChild(trItem);
    menu.appendChild(kgmItem);
    btn.addEventListener('click', function(e){
      e.stopPropagation();
      menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
    });
    document.addEventListener('click', function(e){
      if(!menu.contains(e.target) && e.target !== btn) menu.style.display = 'none';
    });
    screen.appendChild(btn);
    screen.appendChild(menu);
  }
  if(window.MutationObserver){
    new MutationObserver(addSleepMenu).observe(document.body, {subtree:true, childList:true});
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', addSleepMenu);
  } else {
    addSleepMenu();
  }
})();




