    if(old) old.remove();
    var overlay = document.createElement('div');
    overlay.className = 'moe-native-results-overlay';
    overlay.style.cssText = 'position:fixed;left:0;right:0;top:0;bottom:0;z-index:10004;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;';
    var box = document.createElement('div');
