(function(){
  var likedSet = null;
  var loading = false;

  function getAuthHeader(){
    try{
      var data = JSON.parse(localStorage.getItem('MoeData') || '{}');
      var u = data.UserInfo || {}, d = data.Device || {};
      var parts = [];
      if(u.token) parts.push('token=' + u.token);
      if(u.userid) parts.push('userid=' + u.userid);
      if(d.dfid) parts.push('dfid=' + d.dfid);
      if(u.t1) parts.push('t1=' + u.t1);
      if(d.mid) parts.push('KUGOU_API_MID=' + d.mid);
      if(d.guid) parts.push('KUGOU_API_GUID=' + d.guid);
      if(d.serverDev) parts.push('KUGOU_API_DEV=' + d.serverDev);
      if(d.mac) parts.push('KUGOU_API_MAC=' + d.mac);
      return parts.join(';');
    }catch(e){ return ''; }
  }

  function currentSong(){
    try{ return JSON.parse(localStorage.getItem('current_song') || '{}'); }catch(e){ return {}; }
  }

  function api(url, options){
    var auth = getAuthHeader();
    var opt = options || {};
    opt.headers = Object.assign({'Authorization': auth}, opt.headers || {});
    return fetch('http://127.0.0.1:6521' + url, opt).then(function(r){ return r.json().catch(function(){ return null; }); });
  }

  function okRes(res){
    return !!(res && (res.status === 1 || res.error_msg === '' || res.data));
  }

  function updateLikeIcons(liked){
    var candidates = document.querySelectorAll('.like-btn, .moe-like-toggle, .extra-btn');
    var nodes = [];
    for(var ci = 0; ci < candidates.length; ci++){
      var cb = candidates[ci];
      var isHeart = cb.classList.contains('like-btn') || cb.classList.contains('moe-like-toggle') || !!cb.querySelector('.fa-heart') || /喜欢|like|heart/i.test(cb.getAttribute('title') || '');
      if(isHeart) nodes.push(cb);
    }
    for(var i = 0; i < nodes.length; i++){
      var btn = nodes[i];
      btn.classList.toggle('moe-liked', !!liked);
      var icon = btn.querySelector('i');
      if(icon) icon.className = liked ? 'fas fa-heart' : 'far fa-heart';
    }
  }

  function resolveLikeList(){
    var like = localStorage.getItem('like') || '';
    var gid = localStorage.getItem('like_gid') || '';
    if(like && gid) return Promise.resolve({listid:like, gid:gid});
    return api('/user/playlist?pagesize=500&t=' + Date.now()).then(function(res){
      var info = (res && res.data && res.data.info) || [];
      for(var i = 0; i < info.length; i++){
        var p = info[i];
        if(p && p.name === '我喜欢'){
          like = String(p.listid || like || '');
          gid = String(p.list_create_gid || p.global_collection_id || '');
          try{
            if(like) localStorage.setItem('like', like);
            if(gid) localStorage.setItem('like_gid', gid);
          }catch(e){}
          break;
        }
      }
      return {listid:like, gid:gid};
    }).catch(function(){ return {listid:like, gid:gid}; });
  }

  function loadLiked(force){
    if(likedSet && !force) return Promise.resolve(likedSet);
    if(loading) return Promise.resolve(likedSet || new Set());
    loading = true;
    return resolveLikeList().then(function(ref){
      var like = ref && ref.listid ? String(ref.listid) : (localStorage.getItem('like') || '');
      var gid = ref && ref.gid ? String(ref.gid) : (localStorage.getItem('like_gid') || '');
      if(!like || !gid){ likedSet = new Set(); loading = false; updateLikeIcons(false); return likedSet; }
      return api('/playlist/track/all?id=' + encodeURIComponent(gid) + '&pagesize=500&t=' + Date.now()).then(function(res){
        var songs = (res && res.data && res.data.songs) || [];
        likedSet = new Set(songs.map(function(s){ return s.hash; }).filter(Boolean));
        loading = false;
        return likedSet;
      }).catch(function(){ loading = false; likedSet = likedSet || new Set(); return likedSet; });
    }).catch(function(){ loading = false; likedSet = likedSet || new Set(); return likedSet; });
  }

  function findFileId(hash){
    return resolveLikeList().then(function(ref){
      var gid = ref && ref.gid ? String(ref.gid) : (localStorage.getItem('like_gid') || '');
      if(!gid) return '';
      return api('/playlist/track/all?id=' + encodeURIComponent(gid) + '&pagesize=500&t=' + Date.now()).then(function(res){
        var songs = (res && res.data && res.data.songs) || [];
        for(var i = 0; i < songs.length; i++){
          if(String(songs[i].hash) === String(hash)) return songs[i].fileid || songs[i].file_id || '';
        }
        return '';
      }).catch(function(){ return ''; });
    }).catch(function(){ return ''; });
  }

  function toggleLike(like){
    var song = currentSong();
    if(!song || !song.hash || song.isLocal || song.isCloud){
      window.$modal && window.$modal.alert('当前没有可收藏的在线歌曲');
      return Promise.resolve(false);
    }
    return loadLiked(false).then(function(set){
      set = set || likedSet || new Set();
      var liked = set.has(song.hash);
      if(liked){
        return findFileId(song.hash).then(function(fileid){
          if(!fileid){
            window.$message && window.$message.error('未找到该歌曲的收藏记录，请稍后重试');
            return true;
          }
          return api('/playlist/tracks/del?listid=' + encodeURIComponent(like) + '&fileids=' + encodeURIComponent(fileid) + '&t=' + Date.now()).then(function(res){
            if(okRes(res)){
              set.delete(song.hash);
              updateLikeIcons(false);
              window.$message && window.$message.success('已取消喜欢');
              try{ window.dispatchEvent(new CustomEvent('moe-unliked-song',{detail:{hash:song.hash}})); }catch(e){}
              try{ window.dispatchEvent(new Event('moe-refresh-library')); }catch(e){}
              loadLiked(true);
              return false;
            }
            window.$message && window.$message.error((res && (res.error_msg || res.error || res.msg)) || '取消喜欢失败');
            return true;
          });
        });
      }
      var data = encodeURIComponent(String(song.name || '').replace(/,/g, '')) + '|' + encodeURIComponent(song.hash);
      return api('/playlist/tracks/add?listid=' + encodeURIComponent(like) + '&data=' + data + '&t=' + Date.now()).then(function(res){
        if(okRes(res)){
          set.add(song.hash);
          updateLikeIcons(true);
          window.$message && window.$message.success('已添加到我喜欢的音乐');
          try{ window.dispatchEvent(new Event('moe-refresh-library')); }catch(e){}
          return true;
        }
        window.$message && window.$message.error((res && (res.error_msg || res.error || res.msg)) || '收藏失败');
        return false;
      });
    }).catch(function(){
      window.$message && window.$message.error('操作失败，请稍后重试');
      return false;
    });
  }

  window.__moeToggleLike = toggleLike;
  window.__moeGetAuthHeader = getAuthHeader;
  window.__moeRefreshLiked = function(){ return loadLiked(true); };

  setInterval(function(){
    var like = localStorage.getItem('like');
    if(!like){ updateLikeIcons(false); return; }
    loadLiked(false).then(function(set){
      var song = currentSong();
      updateLikeIcons(!!(song && song.hash && set && set.has(song.hash)));
    });
  }, 1200);

  loadLiked(false).then(function(){ var song = currentSong(); updateLikeIcons(!!(song && song.hash && likedSet && likedSet.has(song.hash))); });
})();

(function(){
  var s = document.createElement('style');
  s.id = 'moe-like-state';
  s.textContent = '.like-btn.moe-liked i,.extra-btn.moe-liked i,.moe-like-toggle.moe-liked i{color:#ff4d6d!important;}';
  document.head.appendChild(s);
})();

(function(){
  function isLibrary(){
    return (location.hash || '').indexOf('#/library') === 0;
  }
  function ensureCreateCard(){ return; }
  if(window.MutationObserver){
    new MutationObserver(ensureCreateCard).observe(document.body, {subtree:true, childList:true});
  }
  window.addEventListener('hashchange', ensureCreateCard);
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ensureCreateCard);
  else ensureCreateCard();
})();

(function(){
  function getAuth(){ return window.__moeGetAuthHeader ? window.__moeGetAuthHeader() : ''; }
  function refreshLibrary(){ try{ window.dispatchEvent(new Event('moe-refresh-library')); }catch(e){} }
  function showCreateDialog(){
    var overlay = document.createElement('div');
    overlay.className = 'moe-create-dialog-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:100000;display:flex;align-items:center;justify-content:center;';
    var box = document.createElement('div');
    box.className = 'moe-create-dialog';
    box.style.cssText = 'width:64vw;max-width:420px;min-width:240px;background:var(--card-bg,#fff);border-radius:14px;padding:16px;box-shadow:0 12px 40px rgba(0,0,0,.25);box-sizing:border-box;';
    box.innerHTML = '<h3 style="margin:0 0 12px;font-size:16px;">创建歌单</h3>';
    var input = document.createElement('input');
    input.type = 'text'; input.placeholder = '请输入歌单名称'; input.maxLength = 40;
    input.style.cssText = 'width:100%;box-sizing:border-box;padding:10px 12px;border:1px solid rgba(128,128,128,.35);border-radius:8px;outline:none;background:transparent;color:inherit;';
    var actions = document.createElement('div');
    actions.style.cssText = 'display:flex;gap:10px;justify-content:flex-end;margin-top:14px;';
    var cancel = document.createElement('button'); cancel.textContent = '取消';
    var ok = document.createElement('button'); ok.textContent = '创建';
    var btnCss = 'padding:8px 16px;border-radius:8px;border:1px solid rgba(128,128,128,.35);background:transparent;color:inherit;font-size:14px;';
    cancel.style.cssText = btnCss;
    ok.style.cssText = btnCss + 'background:var(--primary-color,#ff4d6d);border-color:transparent;color:#fff;';
    actions.appendChild(cancel); actions.appendChild(ok);
    box.appendChild(input); box.appendChild(actions); overlay.appendChild(box); document.body.appendChild(overlay);
    function close(){ overlay.remove(); }
    cancel.addEventListener('click', close);
    overlay.addEventListener('click', function(e){ if(e.target === overlay) close(); });
    ok.addEventListener('click', function(){
      var name = (input.value || '').trim();
      if(!name){ input.focus(); return; }
      ok.disabled = true; ok.textContent = '创建中...';
      fetch('http://127.0.0.1:6521/playlist/add', {method:'POST',headers:{'Authorization':getAuth(),'Content-Type':'application/json'},body:JSON.stringify({name:name,type:0})})
        .then(function(r){ return r.json().catch(function(){ return null; }); })
        .then(function(res){
          if(res && (res.status === 1 || res.error_msg === '' || res.data)){
            try{ localStorage.setItem('t', Date.now()); }catch(e){}
            window.$message && window.$message.success('歌单创建成功');
            refreshLibrary(); close();
          } else {
            ok.disabled = false; ok.textContent = '创建';
            window.$message && window.$message.error((res && (res.error_msg || res.error || res.msg)) || '创建歌单失败');
          }
        }).catch(function(){ ok.disabled = false; ok.textContent = '创建'; window.$message && window.$message.error('创建歌单失败'); });
    });
    setTimeout(function(){ input.focus(); }, 80);
  }
  function parseListId(href){
    if(!href) return '';
    var m = String(href).match(/[?&#]listid=([^&]+)/);
    if(!m) return '';
    try{ return decodeURIComponent(m[1]); }catch(e){ return m[1]; }
  }
  function showDeleteMenu(x,y,card,listid){
    var overlay = document.createElement('div');
    overlay.className = 'moe-playlist-menu-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:100001;background:transparent;';
    var menu = document.createElement('div');
    menu.className = 'moe-playlist-menu';
    menu.style.cssText = 'position:fixed;left:' + Math.max(8, Math.min(x, window.innerWidth - 140)) + 'px;top:' + Math.max(8, Math.min(y, window.innerHeight - 70)) + 'px;min-width:130px;background:var(--card-bg,#fff);border-radius:10px;box-shadow:0 8px 28px rgba(0,0,0,.28);overflow:hidden;color:inherit;';
    var item = document.createElement('button');
    item.type = 'button'; item.textContent = '删除歌单';
    item.style.cssText = 'display:block;width:100%;padding:12px 16px;border:0;background:transparent;color:#ff4d6d;font-size:14px;text-align:left;';
    menu.appendChild(item); overlay.appendChild(menu); document.body.appendChild(overlay);
    function close(){ overlay.remove(); }
    overlay.addEventListener('click', close);
    item.addEventListener('click', function(e){
      e.stopPropagation();
      var nameEl = card.querySelector('.album-info h3');
      var name = nameEl ? nameEl.textContent.trim() : '该歌单';
      close();
      var go = function(){
        fetch('http://127.0.0.1:6521/playlist/del?listid=' + encodeURIComponent(listid) + '&t=' + Date.now(), {headers:{'Authorization':getAuth()}})
          .then(function(r){ return r.json().catch(function(){ return null; }); })
          .then(function(res){
            if(res && (res.status === 1 || res.error_msg === '' || res.data)){
              try{ localStorage.setItem('t', Date.now()); }catch(e){}
              window.$message && window.$message.success('歌单已删除');
              refreshLibrary();
            } else {
              window.$message && window.$message.error((res && (res.error_msg || res.error || res.msg)) || '删除歌单失败');
            }
          }).catch(function(){ window.$message && window.$message.error('删除歌单失败'); });
      };
      if(window.$modal && window.$modal.confirm){
        window.$modal.confirm('确定要删除歌单“' + name + '”吗？').then(function(ok){ if(ok) go(); });
      } else if(window.confirm('确定要删除歌单“' + name + '”吗？')){ go(); }
    });
  }
  document.addEventListener('click', function(e){
    var create = e.target && e.target.closest && e.target.closest('.moe-create-playlist-card');
    if(!create) return;
    e.preventDefault(); e.stopPropagation();
    if(e.stopImmediatePropagation) e.stopImmediatePropagation();
    showCreateDialog();
  }, true);
  document.addEventListener('contextmenu', function(e){
    var card = e.target && e.target.closest && e.target.closest('.library-page .music-card');
    if(!card || card.classList.contains('moe-create-playlist-card')) return;
    var tabs = document.querySelectorAll('.library-page .category-tabs button');
    var active = -1;
    for(var i = 0; i < tabs.length; i++){ if(tabs[i].classList.contains('active')){ active = i; break; } }
    if(active !== 0) return;
    var link = card.querySelector('a[href]');
    var listid = parseListId(link && link.getAttribute('href'));
    if(!listid) return;
    e.preventDefault(); e.stopPropagation();
    window.__moeSuppressUntil = Date.now() + 2500;
    showDeleteMenu(e.clientX || 8, e.clientY || 8, card, listid);
  }, true);
  function ensureCreateFab(){
    if(document.querySelector('.moe-create-playlist-fab')) return;
    var fab = document.createElement('button');
    fab.className = 'moe-create-playlist-fab';
    fab.type = 'button';
    fab.title = '创建歌单';
    fab.innerHTML = '<i class="fas fa-plus"></i>';
    fab.style.cssText = 'position:fixed;right:18px;bottom:112px;z-index:9998;width:48px;height:48px;border-radius:50%;border:none;background:var(--primary-color,#ff4d6d);color:#fff;font-size:20px;box-shadow:0 6px 18px rgba(0,0,0,.28);display:none;align-items:center;justify-content:center;';
    fab.addEventListener('click', function(e){ e.preventDefault(); e.stopPropagation(); showCreateDialog(); });
    document.body.appendChild(fab);
    function sync(){
      var on = (location.hash || '').indexOf('#/library') === 0;
      fab.style.display = on ? 'inline-flex' : 'none';
    }
    window.addEventListener('hashchange', sync);
    sync();
  }
  ensureCreateFab();
  window.addEventListener('hashchange', function(){
    if((location.hash || '').indexOf('#/library') === 0){ setTimeout(refreshLibrary, 60); }
  });
})();

(function(){
  document.addEventListener('contextmenu', function(){
    window.__moeSuppressUntil = Date.now() + 2000;
  }, true);
  document.addEventListener('click', function(e){
    if(Date.now() < (window.__moeSuppressUntil || 0) && e.target && e.target.closest && e.target.closest('.song-item, .library-page .music-card')){
      e.stopPropagation();
      e.preventDefault();
      if(e.stopImmediatePropagation) e.stopImmediatePropagation();
    }
  }, true);
})();

(function(){
  function readCurrent(){
    var a = document.querySelector('audio');
    if(!a) return null;
    var name = a.getAttribute('data-song-name') || '';
    var author = a.getAttribute('data-song-author') || '';
    if(!name){
      var t = document.querySelector('.player-container .song-title') || document.querySelector('.song-title');
      name = t ? (t.textContent || '').trim() : (document.title || '');
    }
    if(!author){
      var ar = document.querySelector('.player-container .artist') || document.querySelector('.artist');
      author = ar ? (ar.textContent || '').trim() : '';
    }
    var song = {};
    try{ song = JSON.parse(localStorage.getItem('current_song') || '{}'); }catch(e){}
    var cover = song.img || '';
    if(!cover){
      var img = document.querySelector('.player-container .album-art img') || document.querySelector('.album-art img') || document.querySelector('.lyrics-screen .album-art-container img');
      cover = img ? (img.src || '') : '';
    }
    var title = author ? (name + ' - ' + author) : name;
    return {a:a, title:title, cover:cover};
  }
  if(window.AndroidMediaBridge && !AndroidMediaBridge.__moeArtHooked){
    AndroidMediaBridge.__moeArtHooked = true;
    setInterval(function(){
      try{
        var info = readCurrent();
        if(!info) return;
        if(AndroidMediaBridge.onStateEx){
          var pos = (isFinite(info.a.currentTime) ? info.a.currentTime : 0) * 1000;
          var dur = (isFinite(info.a.duration) ? info.a.duration : 0) * 1000;
          var playing = !info.a.paused && !info.a.ended && info.a.currentTime > 0;
          AndroidMediaBridge.onStateEx(playing, pos, dur, info.title, info.cover);
        }
      }catch(e){}
    }, 700);
  }
})();
